include("auth_owner.php");include("db.php");include("functions.php");$notice='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $item_id=(int)($_POST['item_id']??0);$action=$_POST['action']??'';
 $stmt=mysqli_prepare($conn,"SELECT item_id,item_name,status,Image FROM items WHERE item_id=? AND owner_id=? LIMIT 1");mysqli_stmt_bind_param($stmt,"ii",$item_id,$owner_id);mysqli_stmt_execute($stmt);$item=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));mysqli_stmt_close($stmt);
 if(!$item)$error="Item not found or you do not own it."; elseif($action==='toggle'){$new=$item['status']==='available'?'unavailable':'available';if($item['status']==='rented')$error="A rented item cannot be toggled manually.";else{$stmt=mysqli_prepare($conn,"UPDATE items SET status=? WHERE item_id=? AND owner_id=?");mysqli_stmt_bind_param($stmt,"sii",$new,$item_id,$owner_id);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$notice="Item status changed to $new.";}}
 elseif($action==='delete'){$stmt=mysqli_prepare($conn,"SELECT COUNT(*) c FROM rental_requests WHERE item_id=?");mysqli_stmt_bind_param($stmt,"i",$item_id);mysqli_stmt_execute($stmt);$count=(int)(mysqli_fetch_assoc(mysqli_stmt_get_result($stmt))['c']??0);mysqli_stmt_close($stmt);if($count)$error="Items with rental history cannot be deleted. Disable the item instead.";else{$stmt=mysqli_prepare($conn,"DELETE FROM items WHERE item_id=? AND owner_id=?");mysqli_stmt_bind_param($stmt,"ii",$item_id,$owner_id);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);if($item['Image']&&str_starts_with($item['Image'],'uploads/items/')){$path=__DIR__.'/'. $item['Image'];if(is_file($path))@unlink($path);}$notice="Item deleted.";}}
}
$search=trim($_GET['search']??'');$status=$_GET['status']??'all';$valid=['all','available','unavailable','rented'];if(!in_array($status,$valid,true))$status='all';
if($search!=='' && ctype_digit($search)){
    $like='%'.$search.'%'; $search_id=(int)$search;
    if($status==='all'){ $stmt=mysqli_prepare($conn,"SELECT * FROM items WHERE owner_id=? AND (item_name LIKE ? OR item_id=?) ORDER BY item_id DESC"); mysqli_stmt_bind_param($stmt,"isi",$owner_id,$like,$search_id); }
    else { $stmt=mysqli_prepare($conn,"SELECT * FROM items WHERE owner_id=? AND status=? AND (item_name LIKE ? OR item_id=?) ORDER BY item_id DESC"); mysqli_stmt_bind_param($stmt,"issi",$owner_id,$status,$like,$search_id); }
}elseif($search!==''){
    $like='%'.$search.'%';
    if($status==='all'){ $stmt=mysqli_prepare($conn,"SELECT * FROM items WHERE owner_id=? AND item_name LIKE ? ORDER BY item_id DESC"); mysqli_stmt_bind_param($stmt,"is",$owner_id,$like); }
    else { $stmt=mysqli_prepare($conn,"SELECT * FROM items WHERE owner_id=? AND status=? AND item_name LIKE ? ORDER BY item_id DESC"); mysqli_stmt_bind_param($stmt,"iss",$owner_id,$status,$like); }
}else{
    if($status==='all'){ $stmt=mysqli_prepare($conn,"SELECT * FROM items WHERE owner_id=? ORDER BY item_id DESC"); mysqli_stmt_bind_param($stmt,"i",$owner_id); }
    else { $stmt=mysqli_prepare($conn,"SELECT * FROM items WHERE owner_id=? AND status=? ORDER BY item_id DESC"); mysqli_stmt_bind_param($stmt,"is",$owner_id,$status); }
}
mysqli_stmt_execute($stmt);$res=mysqli_stmt_get_result($stmt);$items=[];while($x=mysqli_fetch_assoc($res))$items[]=$x;mysqli_stmt_close($stmt);$current='items';
