tn owner-btn-edit" href="edit_item.php?item_id=<?php echo (int)$i['item_id']; ?>">Edit</a><?php if($i['status']!=='rented'):?><form method="post"><input type="hidden" name="item_id" value="<?php echo (int)$i['item_id']; ?>"><button class="owner-btn owner-btn-neutral" name="action" value="toggle"><?php echo $i['status']==='available'?'Disable':'Enable'; ?></button></form><?php endif;?><form method="post" onsubmit="return confirm('Delete this item?');"><input type="hidden" name="item_id" value="<?php echo (int)$i['item_id']; ?>"><button class="owner-btn owner-btn-danger" name="action" value="delete">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section></main></div></body></html>
